#define FW_ROCKETS 4u
#define FW_SPARKS 160u
#define FW_G (40*256)
#define FW_SG (18*256)
typedef struct { int32_t x,y,vx,vy,drift,wamp; uint16_t wob; uint8_t alive; int16_t tx[2],ty[2]; } Rocket;
typedef struct { int32_t x,y; int16_t vx,vy,life; uint8_t alive; } Spark;
static Rocket s_rk[FW_ROCKETS];
static Spark s_sp[FW_SPARKS];
static uint32_t s_rng=0x2545F491u,s_lastT=0u,s_nextSpawn=60u,s_fwClock=0u;
static uint8_t s_side=0u,s_drawn=0u;
static const uint8_t s_starXY[10][2]={{4,6},{18,14},{30,3},{110,4},{122,18},{100,9},{8,40},{120,40},{14,52},{116,56}};
static uint32_t Rnd(void) { s_rng^=s_rng<<13; s_rng^=s_rng>>17; s_rng^=s_rng<<5; return s_rng; }
static uint32_t RndN(uint32_t n) { return Rnd()%n; }
static void Fw_Burst(int32_t px,int32_t py)
{
    uint32_t n,i,base;
    uint16_t k=0u;
    int32_t spd,sp,ang;
    uint8_t ring;
    n=26u+RndN(15u); base=Rnd()&65535u; spd=22+(int32_t)RndN(40u); ring=(uint8_t)(RndN(3u)==0u);
    for(i=0u;i<n;i++) {
        while(k<FW_SPARKS && s_sp[k].alive) { k++; } if(k>=FW_SPARKS) { break; }
        ang=(int32_t)((base+i*65536u/n)&65535u)+(int32_t)RndN(2400u)-1200; ang &= 65535;
        sp=ring?spd:spd*(int32_t)(40u+RndN(61u))/100;
        s_sp[k].x=px*256+128; s_sp[k].y=py*256+128;
        s_sp[k].vx=(int16_t)(Sin14((uint16_t)ang)*sp/64); s_sp[k].vy=(int16_t)(-Cos14((uint16_t)ang)*sp/64);
        s_sp[k].life=(int16_t)(700+(int32_t)RndN(650u)); s_sp[k].alive=1u;
    }
}
static void Fw_Spawn(void)
{
    uint16_t i;
    int32_t x;
    for(i=0u;i<FW_ROCKETS;i++) { if(!s_rk[i].alive) { break; } } if(i>=FW_ROCKETS) { return; }
    s_side^=1u; x=s_side?8+(int32_t)RndN(28u):92+(int32_t)RndN(28u);
    s_rk[i].x=x*256; s_rk[i].y=64*256; s_rk[i].vx=0; s_rk[i].vy=-(int32_t)(55u+RndN(14u))*256;
    s_rk[i].drift=((int32_t)RndN(25u)-12)*256; s_rk[i].wamp=(int32_t)(12u+RndN(22u))*256; s_rk[i].wob=(uint16_t)Rnd();
    s_rk[i].tx[0]=s_rk[i].tx[1]=(int16_t)x; s_rk[i].ty[0]=s_rk[i].ty[1]=64; s_rk[i].alive=1u;
}
static void Fw_Step(int32_t dt)
{
    uint16_t i;
    for(i=0u;i<FW_ROCKETS;i++) {
        Rocket *r=&s_rk[i];
        int32_t hx,hy;
        if(!r->alive) { continue; }
        r->wob=(uint16_t)(r->wob+(uint32_t)(dt*94)); r->vx=r->drift+Sin14(r->wob)*r->wamp/16384;
        r->vy+=FW_G*dt/1000; r->x+=r->vx*dt/1000; r->y+=r->vy*dt/1000; hx=r->x>>8; hy=r->y>>8;
        r->tx[1]=r->tx[0]; r->ty[1]=r->ty[0]; r->tx[0]=(int16_t)hx; r->ty[0]=(int16_t)hy;
        if(r->vy>=0 || hy<6) { if(hx>=0 && hx<128 && hy>=0 && hy<64) { Fw_Burst(hx,hy); } r->alive=0u; }
        else if(hx < -4 || hx>131) { r->alive=0u; }
    }
    for(i=0u;i<FW_SPARKS;i++) {
        Spark *s=&s_sp[i];
        if(!s->alive) { continue; } s->life=(int16_t)(s->life-dt); if(s->life<=0) { s->alive=0u; continue; }
        s->vx=(int16_t)(s->vx-s->vx*dt/800); s->vy=(int16_t)(s->vy+FW_SG*dt/1000-s->vy*dt/800);
        s->x+=(int32_t)s->vx*dt/1000; s->y+=(int32_t)s->vy*dt/1000;
    }
}
static void Fw_Draw(void)
{
    uint16_t i;
    int32_t px,py,tx,ty,spd;
    for(i=0u;i<FW_ROCKETS;i++) { if(s_rk[i].alive) { OLED_DrawLine(s_rk[i].tx[1],s_rk[i].ty[1],s_rk[i].tx[0],s_rk[i].ty[0],OLED_WHITE); } }
    for(i=0u;i<FW_SPARKS;i++) {
        Spark *s=&s_sp[i];
        if(!s->alive || (s->life<260 && ((s->life/80)&1))) { continue; }
        px=s->x>>8; py=s->y>>8; OLED_DrawPixel(px,py,OLED_WHITE);
        spd=((s->vx<0)?-s->vx:s->vx)+((s->vy<0)?-s->vy:s->vy);
        if(spd>30*256) { tx=(s->x-(int32_t)s->vx/25)>>8; ty=(s->y-(int32_t)s->vy/25)>>8; OLED_DrawLine(px,py,tx,ty,OLED_WHITE); }
    }
}
void Scene_AlarmBegin(uint32_t nowMs)
{
    uint16_t i;
    for(i=0u;i<FW_ROCKETS;i++) { s_rk[i].alive=0u; } for(i=0u;i<FW_SPARKS;i++) { s_sp[i].alive=0u; }
    s_rng=0x2545F491u^nowMs; if(!s_rng) { s_rng=1u; }
    s_lastT=nowMs; s_nextSpawn=60u; s_side=0u; s_fwClock=0u; s_drawn=0u;
    CatAnim_Reset(nowMs);
}
/* Frame cadence is owned by the cat player (33/33/34 ms = 30 fps). Fireworks
 * integrate the real elapsed time, so both stay smooth and in step. Each frame
 * is drawn into GRAM: fireworks first, transparent cat foreground second, then
 * one display update. */
uint8_t Scene_Alarm(uint32_t nowMs)
{
    uint32_t tmp;
    uint16_t i;
    int32_t dt=0,px;
    if(s_drawn) {
        if(!CatAnim_Tick(nowMs)) { return 0u; }
        dt=(int32_t)(nowMs-s_lastT); if(dt<0) { dt=0; } if(dt>100) { dt=100; }
        s_lastT=nowMs; s_fwClock+=(uint32_t)dt;
    } else { s_drawn=1u; s_lastT=nowMs; CatAnim_Reset(nowMs); }
    if((int32_t)(s_fwClock-s_nextSpawn)>=0) { Fw_Spawn(); s_nextSpawn=s_fwClock+220u+RndN(360u); }
    Fw_Step(dt); OLED_Clear();
    for(i=0u;i<10u;i++) { tmp=s_fwClock/260u+(uint32_t)i*3u; if((tmp&3u)!=0u) { OLED_DrawPixel(s_starXY[i][0],s_starXY[i][1],OLED_WHITE); } }
    for(px=0;px<128;px+=2) { if(((px+(int32_t)(s_fwClock/50u))&15)<7) { OLED_DrawPixel(px,61,OLED_WHITE); } }
    Fw_Draw(); CatAnim_Draw(); return 1u;
}
